import{_ as o,o as t,c as s,a2 as r}from"./chunks/framework.e4u2V5E7.js";const p=JSON.parse('{"title":"Postgresql","description":"Postgresql reference documentation","frontmatter":{"title":"Postgresql","description":"Postgresql reference documentation"},"headers":[],"relativePath":"knowledge/postgresql.md","filePath":"knowledge/postgresql.md","lastUpdated":1784485118000}'),a={name:"knowledge/postgresql.md"};function n(i,e,c,l,d,g){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="postgresql" tabindex="-1">Postgresql <a class="header-anchor" href="#postgresql" aria-label="Permalink to &quot;Postgresql&quot;">​</a></h1><h1 id="postgresql-knowledge-document" tabindex="-1">PostgreSQL Knowledge Document <a class="header-anchor" href="#postgresql-knowledge-document" aria-label="Permalink to &quot;PostgreSQL Knowledge Document&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>PostgreSQL is a powerful, open-source relational database known for its extensibility, standards compliance, and advanced features. It supports complex queries, JSONB storage, full-text search, geospatial data, and custom extensions. Understanding PostgreSQL deeply is essential for building performant, reliable applications on Supabase or any self-hosted deployment.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="data-types" tabindex="-1">Data Types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data Types&quot;">​</a></h3><p>PostgreSQL offers rich data types: <code>serial</code>/<code>bigserial</code> for auto-incrementing IDs, <code>uuid</code> for distributed IDs, <code>jsonb</code> for structured semi-schema data, <code>text</code> over <code>varchar</code> (no performance difference, more flexible), <code>timestamptz</code> over <code>timestamp</code> (timezone-aware), and <code>numeric</code> over <code>float</code> for exact arithmetic.</p><h3 id="indexing" tabindex="-1">Indexing <a class="header-anchor" href="#indexing" aria-label="Permalink to &quot;Indexing&quot;">​</a></h3><ul><li><strong>B-tree:</strong> Default index. Efficient for equality and range queries. Use for most WHERE clauses.</li><li><strong>GIN (Generalized Inverted Index):</strong> Optimized for containment queries on arrays, JSONB, and full-text search vectors.</li><li><strong>GiST (Generalized Search Tree):</strong> Used for geospatial data (PostGIS), range types, and fuzzy text search.</li><li><strong>BRIN (Block Range Index):</strong> Compact index for physically ordered data. Ideal for large time-series tables.</li><li><strong>Partial Index:</strong> Index only rows matching a condition. Smaller and faster than full-table indexes.</li></ul><h3 id="query-execution" tabindex="-1">Query Execution <a class="header-anchor" href="#query-execution" aria-label="Permalink to &quot;Query Execution&quot;">​</a></h3><p><code>EXPLAIN ANALYZE</code> shows the actual execution plan with timing and row estimates. Key things to look for: sequential scans on large tables (missing index), nested loops vs hash joins, and actual vs estimated row counts (statistics accuracy).</p><h3 id="common-table-expressions-ctes" tabindex="-1">Common Table Expressions (CTEs) <a class="header-anchor" href="#common-table-expressions-ctes" aria-label="Permalink to &quot;Common Table Expressions (CTEs)&quot;">​</a></h3><p>CTEs with <code>WITH</code> clauses improve readability for complex queries. PostgreSQL 12+ optimizes CTEs as optimization fences by default — use <code>MATERIALIZED</code> or <code>NOT MATERIALIZED</code> to control behavior.</p><h3 id="window-functions" tabindex="-1">Window Functions <a class="header-anchor" href="#window-functions" aria-label="Permalink to &quot;Window Functions&quot;">​</a></h3><p><code>ROW_NUMBER()</code>, <code>RANK()</code>, <code>LAG()</code>, <code>LEAD()</code>, <code>SUM() OVER(PARTITION BY ... ORDER BY ...)</code> enable analytical queries without subqueries. Essential for pagination, ranking, and running totals.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Use <code>timestamptz</code> everywhere</strong> — Always store timezone-aware timestamps. PostgreSQL stores them in UTC and converts on display. Using <code>timestamp</code> loses timezone context.</p></li><li><p><strong>Prefer <code>text</code> over <code>varchar(n)</code></strong> — There is no performance difference. <code>text</code> is more flexible and PostgreSQL-specific. Use <code>CHECK</code> constraints if you need length limits.</p></li><li><p><strong>Create indexes on foreign keys</strong> — PostgreSQL does not auto-index foreign key columns. Every FK column used in JOINs should have an index.</p></li><li><p><strong>Use <code>EXPLAIN (ANALYZE, BUFFERS, FORMAT TEXT)</code> for query debugging</strong> — This shows actual execution time, buffer usage, and the full plan. Always use it when optimizing slow queries.</p></li><li><p><strong>Partition large tables by range or hash</strong> — Tables over 100M rows benefit from partitioning. Range partition by date for time-series; hash partition for even distribution.</p></li><li><p><strong>Use connection pooling (PgBouncer)</strong> — PostgreSQL forks a process per connection. PgBouncer or PgCat multiplexes connections, essential for serverless environments.</p></li><li><p><strong>Set <code>statement_timeout</code> and <code>idle_in_transaction_session_timeout</code></strong> — Prevent long-running queries from consuming resources. Set <code>statement_timeout</code> to 30s for OLTP workloads.</p></li><li><p><strong>Use <code>jsonb</code> over <code>json</code></strong> — <code>jsonb</code> is binary, supports indexing (GIN), supports containment operators (<code>@&gt;</code>), and is significantly faster for querying.</p></li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><p><strong>Using <code>SELECT *</code> in application queries</strong> — Always specify columns. <code>SELECT *</code> fetches unnecessary data, breaks on schema changes, and prevents index-only scans.</p></li><li><p><strong>Running migrations against production without staging</strong> — Test every migration against a production-like dataset first. Migrations are not reversible by default.</p></li><li><p><strong>Over-normalizing data</strong> — Splitting every attribute into a separate table creates JOIN-heavy queries. Denormalize when read performance matters more than write flexibility.</p></li><li><p><strong>Ignoring <code>ANALYZE</code> statistics</strong> — PostgreSQL uses statistics to choose query plans. Run <code>ANALYZE</code> after large data changes or enable <code>autoanalyze</code>.</p></li><li><p><strong>Using <code>LIKE &#39;%pattern%&#39;</code> for search</strong> — Prefix wildcards prevent index usage. Use full-text search (<code>tsvector</code> + GIN index) or trigram indexes (<code>pg_trgm</code>) for substring matching.</p></li><li><p><strong>Storing computed values without triggers</strong> — If a derived column is frequently queried, compute it on write (via trigger) rather than on every read.</p></li><li><p><strong>Using <code>BIGSERIAL</code> without thinking</strong> — UUIDs or ULIDs are often better for distributed systems. Sequential IDs create write contention and expose business metrics.</p></li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><p><strong>Not using <code>COALESCE</code> for nullable aggregates</strong> — <code>SUM()</code> returns <code>NULL</code> when no rows match. Use <code>COALESCE(SUM(amount), 0)</code> to get a default.</p></li><li><p><strong>Forgetting <code>GROUP BY</code> with aggregate functions</strong> — PostgreSQL enforces strict SQL standard: all non-aggregated columns must appear in <code>GROUP BY</code>.</p></li><li><p><strong>Using <code>OFFSET</code> for deep pagination</strong> — <code>OFFSET 100000</code> scans and discards 100k rows. Use cursor-based pagination with <code>WHERE id &gt; last_seen_id</code>.</p></li><li><p><strong>Not vacuuming after bulk deletes</strong> — Deleted rows are dead tuples that consume space until vacuumed. Run <code>VACUUM</code> or ensure <code>autovacuum</code> is enabled.</p></li><li><p><strong>Assuming <code>NOW()</code> is monotonic</strong> — Clock adjustments can cause <code>NOW()</code> to return earlier values. Use <code>clock_timestamp()</code> when you need actual wall-clock time.</p></li><li><p><strong>Using <code>NOT IN</code> with subqueries containing NULLs</strong> — <code>NOT IN (SELECT ...)</code> returns empty if any subquery result is NULL. Use <code>NOT EXISTS</code> instead.</p></li><li><p><strong>Ignoring connection limits</strong> — Default <code>max_connections</code> is 100. Exceeding it causes connection refused errors. Use PgBouncer to manage connection pool.</p></li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><ul><li><strong>Use PostgreSQL when:</strong> You need ACID compliance, complex joins, JSONB storage, full-text search, geospatial queries, or extensibility via extensions.</li><li><strong>Use JSONB columns when:</strong> Your data has variable structure or you need flexible schemas within a relational model. Prefer columns for frequently queried fields.</li><li><strong>Partition when:</strong> Tables exceed 100M rows or you need data lifecycle management (archival, deletion by date range).</li><li><strong>Choose UUID vs BIGSERIAL:</strong> Use UUID for distributed systems, microservices, or when IDs are exposed publicly. Use BIGSERIAL for internal high-performance OLTP.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>PostgreSQL Official Docs: <a href="https://www.postgresql.org/docs/15/" target="_blank" rel="noreferrer">https://www.postgresql.org/docs/15/</a></li><li>PostgreSQL Wiki: <a href="https://wiki.postgresql.org" target="_blank" rel="noreferrer">https://wiki.postgresql.org</a></li><li>Use The Index, Luke (Indexing Guide): <a href="https://use-the-index-luke.com" target="_blank" rel="noreferrer">https://use-the-index-luke.com</a></li><li>pgMustard (EXPLAIN visualizer): <a href="https://www.pgmustard.com" target="_blank" rel="noreferrer">https://www.pgmustard.com</a></li><li>PgBouncer: <a href="https://www.pgbouncer.org" target="_blank" rel="noreferrer">https://www.pgbouncer.org</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><code>pg_dump</code> and <code>pg_restore</code> are your backup/restore tools. Use <code>--no-owner --no-privileges</code> for portability.</li><li>Enable <code>pg_stat_statements</code> for query performance monitoring in production.</li><li>Use <code>\\d+ table_name</code> in psql to see table size, indexes, and storage parameters.</li><li>Set <code>log_min_duration_statement = 250</code> to log queries taking over 250ms.</li><li>For Supabase, access PostgreSQL via the connection string in Settings &gt; Database.</li><li>PostgreSQL 15 introduced <code>MERGE</code> statement for upsert-like operations at the SQL level.</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',29)])])}const h=o(a,[["render",n]]);export{p as __pageData,h as default};
